'use strict';

// MAIN //

/**
* Creates a compact, provider-neutral index projection of an origin.
*
* @param {Object} origin - stored origin
* @returns {Object} origin summary
*/
function originSummary( origin ) {
	if ( origin.type === 'ci_artifact' ) {
		return {
			'type': 'ci_artifact',
			'provider': origin.provider,
			'project': structuredClone( origin.project )
		};
	}
	return {
		'type': 'url',
		'endpoint': origin.endpoint
	};
}


// EXPORTS //

module.exports = originSummary;
